import{_ as o,o as t,c as a,ag as n}from"./chunks/framework.B_zcDAFh.js";const u=JSON.parse('{"title":"Boing Behavior","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-behavior.md","filePath":"guide/boing-behavior.md"}'),i={name:"guide/boing-behavior.md"};function r(s,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="boing-behavior" tabindex="-1">Boing Behavior <a class="header-anchor" href="#boing-behavior" aria-label="Permalink to &quot;Boing Behavior&quot;">​</a></h1><p>Add the <strong>Boing Behavior</strong> component to make an object react bouncily to changes in its own position and rotation.</p><p>Any change to the object&#39;s transform during <code>Update</code> is picked up by the component and turned into a bouncy effect during <code>LateUpdate</code>.</p><h2 id="typical-use" tabindex="-1">Typical Use <a class="header-anchor" href="#typical-use" aria-label="Permalink to &quot;Typical Use&quot;">​</a></h2><p>Attach <code>BoingBehavior</code> to an object you intend to move directly — for example, one that follows the mouse cursor. The object will lag behind the cursor as if connected to it by a spring, then settle back when the cursor stops.</p><p>The same applies to any script-driven motion: teleports, tween targets, AI movement, etc. As long as the transform is updated during <code>Update</code>, the spring response shows up automatically.</p><h2 id="avoiding-sudden-jumps-after-teleports" tabindex="-1">Avoiding Sudden Jumps After Teleports <a class="header-anchor" href="#avoiding-sudden-jumps-after-teleports" aria-label="Permalink to &quot;Avoiding Sudden Jumps After Teleports&quot;">​</a></h2><p>When you intentionally snap an object to a new position or rotation, call <code>BoingBehavior.HandleTeleport()</code> immediately afterward. This resets the spring&#39;s internal state so the next <code>LateUpdate</code> doesn&#39;t interpret the teleport as a high-velocity displacement and overshoot wildly.</p><h2 id="optional-effects" tabindex="-1">Optional Effects <a class="header-anchor" href="#optional-effects" aria-label="Permalink to &quot;Optional Effects&quot;">​</a></h2><ul><li><strong>Scale effects</strong> — off by default; can be enabled in the Inspector to make scale changes also produce a bouncy response.</li><li><strong>Axis locks</strong> — translational and rotational effects can be locked along specific axes in either global or local space.</li></ul><p>See the <a href="/boing-kit/api/boing-behavior.html">API reference</a> for the full property list, or hover over fields in the Inspector for tooltips.</p>',11)])])}const f=o(i,[["render",r]]);export{u as __pageData,f as default};
